spec.setup_code:
var T = 14, B = [0, 3.5, 7.5, 10.5, 14];
var A = [[-1.5,0.3],[-0.8,-0.3],[-0.1,0.2],[0.6,-0.3],[1.3,0.2],[-0.8,-1.1],[-0.1,1.0],[0.6,-1.1],[1.9,-0.4],[1.3,1.0]];
var BONDS = [[0,1],[1,2],[2,3],[3,4],[1,5],[2,6],[3,7],[4,8],[4,9]];
var COL = ['#B4552F','#0B4FC0','#0B4FC0','#0B4FC0','#0B4FC0','#138374','#6A47C2','#138374','#138374','#6A47C2'];
var INK = '#04204B', SEC = '#3D5F91', FAINT = '#8098BC', BLUE = '#0B4FC0', WARM = '#B4552F';
function seed(s) { return function () { s |= 0; s = s + 0x6D2B79F5 | 0; var t = Math.imul(s ^ s >>> 15, 1 | s); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
var rnd = seed(7);
var N = [];
for (var i = 0; i < 10; i++) N.push([(rnd() - 0.5) * 1.2, (rnd() - 0.5) * 1.2]);
function hr(n) { var x = Math.sin(n * 127.1 + 3.7) * 43758.5453; return x - Math.floor(x); }
function sm(x) { x = Math.max(0, Math.min(1, x)); return x * x * (3 - 2 * x); }
function weight(i, t) {
  var c = (B[i] + B[i + 1]) / 2, tt = t;
  if (tt - c > T / 2) tt -= T;
  if (c - tt > T / 2) tt += T;
  var w = sm((tt - B[i]) / 0.8 + 0.5) * (1 - sm((tt - B[i + 1]) / 0.8 + 0.5));
  return { w: w, lt: tt - B[i], tt: tt };
}
function mol(ctx, cx, cy, ang, u, a, ghost, loc) {
  var c = Math.cos(ang), s = Math.sin(ang), P = [], i;
  for (i = 0; i < loc.length; i++) P.push([cx + u * (loc[i][0] * c - loc[i][1] * s), cy + u * (loc[i][0] * s + loc[i][1] * c)]);
  ctx.globalAlpha = a;
  ctx.strokeStyle = ghost ? FAINT : INK;
  ctx.lineWidth = ghost ? 1.5 : Math.max(2, u * 0.07);
  ctx.lineCap = 'round';
  for (i = 0; i < BONDS.length; i++) {
    ctx.beginPath(); ctx.moveTo(P[BONDS[i][0]][0], P[BONDS[i][0]][1]); ctx.lineTo(P[BONDS[i][1]][0], P[BONDS[i][1]][1]); ctx.stroke();
  }
  for (i = 0; i < P.length; i++) {
    ctx.beginPath(); ctx.arc(P[i][0], P[i][1], u * 0.19, 0, 6.2832);
    if (ghost) { ctx.fillStyle = '#ffffff'; ctx.fill(); ctx.lineWidth = 1.5; ctx.strokeStyle = FAINT; ctx.stroke(); }
    else { ctx.fillStyle = COL[i]; ctx.fill(); ctx.lineWidth = 1; ctx.strokeStyle = INK; ctx.stroke(); }
  }
  ctx.globalAlpha = 1;
  return P;
}
function arrow(ctx, x1, y1, x2, y2, col, a, lw) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy);
  if (L < 2) return;
  var ux = dx / L, uy = dy / L, h = Math.min(8, L * 0.6);
  ctx.globalAlpha = a; ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = lw;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2 - ux * h * 0.6, y2 - uy * h * 0.6); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - ux * h - uy * h * 0.5, y2 - uy * h + ux * h * 0.5);
  ctx.lineTo(x2 - ux * h + uy * h * 0.5, y2 - uy * h - ux * h * 0.5);
  ctx.closePath(); ctx.fill();
  ctx.globalAlpha = 1;
}
function txt(ctx, s, x, y, col, al, a, font) {
  ctx.globalAlpha = a; ctx.fillStyle = col; ctx.textAlign = al; ctx.font = font || '12px sans-serif';
  ctx.fillText(s, x, y); ctx.globalAlpha = 1;
}
function wrap(ctx, s, maxW) {
  var words = s.split(' '), lines = [], cur = '';
  ctx.font = '12px sans-serif';
  for (var i = 0; i < words.length; i++) {
    var test = cur ? cur + ' ' + words[i] : words[i];
    if (ctx.measureText(test).width > maxW && cur) { lines.push(cur); cur = words[i]; } else cur = test;
  }
  if (cur) lines.push(cur);
  return lines;
}
var TOP = ['Same structure in any pose', 'Equivariant denoiser (RFdiffusion)', 'Augmentation (AlphaFold 3)', "RFdiffusion's state: one rigid frame per residue"];
var BOT = ['Rotating by R and shifting by t changes the coordinates x → Rx + t, not the molecule.',
  'Rotate the input by R and the predicted corrections rotate by R too: f(Rx) = R f(x).',
  'AF3 uses a plain transformer and random rotations instead: it learns the symmetry from data',
  'Frame = (t, R): the Cα position plus a rotation, stored for every residue.'];
function deg(a) { return Math.round(((a * 180 / Math.PI) % 360 + 360) % 360); }

return {
  draw: function (ctx, W, H, time, dt) {
    ctx.globalAlpha = 1;
    ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, W, H);
    var t = time % T, i;
    var top = 62, bot = H - 64, rh = bot - top, cy0 = (top + bot) / 2;
    var u = Math.min(W / 9, rh / 5.2);
    var ax = Math.max(0, W / 2 - 2.3 * u - 6), ay = Math.max(0, rh / 2 - 2.2 * u);
    var ws = [], q;
    for (i = 0; i < 4; i++) ws.push(weight(i, t));

    // phase 1: free rigid motion
    q = ws[0];
    if (q.w > 0.01) {
      var a1 = 0.3 + 0.9 * q.tt, x1 = W / 2 + ax * Math.sin(0.6 * q.tt + 0.5), y1 = cy0 + ay * Math.sin(0.9 * q.tt + 1);
      for (i = 1; i <= 6; i++) {
        var tp = q.tt - i * 0.18;
        ctx.globalAlpha = q.w * 0.25 * (1 - i / 7); ctx.fillStyle = FAINT;
        ctx.beginPath(); ctx.arc(W / 2 + ax * Math.sin(0.6 * tp + 0.5), cy0 + ay * Math.sin(0.9 * tp + 1), 3, 0, 6.2832); ctx.fill();
      }
      ctx.globalAlpha = 1;
      mol(ctx, x1, y1, a1, u, q.w, false, A);
      txt(ctx, 'θ = ' + deg(a1) + '°   t = (' + Math.round(x1) + ', ' + Math.round(y1) + ')', W / 2, 50, SEC, 'center', q.w, '12px sans-serif');
    }

    // phase 2: equivariant denoiser
    q = ws[1];
    if (q.w > 0.01) {
      var lt = q.lt, a2 = 0.4 + 0.8 * lt, x2 = W / 2 + ax * 0.4 * Math.sin(0.5 * lt + 1);
      var f = 1 - 0.8 * sm((lt - 1.8) / 1.6);
      var noisy = [];
      for (i = 0; i < 10; i++) noisy.push([A[i][0] + N[i][0] * f, A[i][1] + N[i][1] * f]);
      var Pg = mol(ctx, x2, cy0, a2, u, q.w * 0.7, true, A);
      var cs = Math.cos(a2), sn = Math.sin(a2);
      var Pn = [];
      for (i = 0; i < 10; i++) Pn.push([x2 + u * (noisy[i][0] * cs - noisy[i][1] * sn), cy0 + u * (noisy[i][0] * sn + noisy[i][1] * cs)]);
      for (i = 0; i < 10; i++) arrow(ctx, Pn[i][0], Pn[i][1], Pg[i][0], Pg[i][1], WARM, q.w, 2);
      mol(ctx, x2, cy0, a2, u, q.w * 0.9, false, noisy);
      txt(ctx, 'noisy xₜ + predicted correction, θ = ' + deg(a2) + '°', W / 2, 50, SEC, 'center', q.w, '12px sans-serif');
    }

    // phase 3: augmentation
    q = ws[2];
    if (q.w > 0.01) {
      var lt3 = q.lt + 1, cnt = 0;
      for (var s = 0; s < 6; s++) {
        var per = 1.2, ph = lt3 + s * 0.2 + 5, k = Math.floor(ph / per), fr = (ph % per) / per;
        var id = s * 97 + k * 13;
        var xr = W / 2 + (hr(id) - 0.5) * 2 * ax, yr = cy0 + (hr(id + 1) - 0.5) * 2 * ay;
        mol(ctx, xr, yr, hr(id + 2) * 6.2832, u, q.w * 0.42 * Math.sin(3.1416 * fr), false, A);
      }
      cnt = Math.floor(lt3 * 5) + 1;
      txt(ctx, 'training sample ' + cnt + ': random R, t', W / 2, 50, SEC, 'center', q.w, '12px sans-serif');
    }

    // phase 4: residue frame
    q = ws[3];
    if (q.w > 0.01) {
      var lt4 = q.lt, a4 = 0.3 + 0.5 * Math.sin(lt4 * 0.9), x4 = W / 2 + ax * 0.3 * Math.sin(0.6 * lt4), y4 = cy0;
      var P4 = mol(ctx, x4, y4, a4, u, q.w * 0.3, false, A);
      var ox = 26, oy = bot - 4, cx4 = P4[2][0], cy4 = P4[2][1];
      ctx.globalAlpha = q.w * 0.6; ctx.strokeStyle = FAINT; ctx.lineWidth = 1.5; ctx.setLineDash([4, 4]);
      ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(cx4, cy4); ctx.stroke(); ctx.setLineDash([]);
      ctx.globalAlpha = q.w * 0.8; ctx.beginPath(); ctx.moveTo(ox - 5, oy); ctx.lineTo(ox + 5, oy); ctx.moveTo(ox, oy - 5); ctx.lineTo(ox, oy + 5); ctx.stroke();
      ctx.globalAlpha = 1;
      txt(ctx, 'origin', ox + 8, oy - 6, FAINT, 'left', q.w, '11px sans-serif');
      txt(ctx, 't', (ox + cx4) / 2 + 8, (oy + cy4) / 2 - 6, SEC, 'left', q.w, 'italic 13px sans-serif');
      var L = 1.3 * u, c4 = Math.cos(a4), s4 = Math.sin(a4);
      var e1 = [cx4 + L * c4, cy4 + L * s4], e2 = [cx4 - L * s4, cy4 + L * c4];
      arrow(ctx, cx4, cy4, e1[0], e1[1], BLUE, q.w, 3);
      arrow(ctx, cx4, cy4, e2[0], e2[1], WARM, q.w, 3);
      txt(ctx, 'e₁', e1[0] + 6 * c4 + 2, e1[1] + 6 * s4 + 4, BLUE, 'left', q.w, '12px sans-serif');
      txt(ctx, 'e₂', e2[0] - 6 * s4 - 8, e2[1] + 6 * c4 + 10, WARM, 'left', q.w, '12px sans-serif');
      ctx.globalAlpha = q.w; ctx.fillStyle = INK; ctx.beginPath(); ctx.arc(cx4, cy4, 6, 0, 6.2832); ctx.fill();
      ctx.globalAlpha = 1;
      txt(ctx, 'Cα', cx4 - 0.45 * L * (c4 - s4) - 8, cy4 - 0.45 * L * (s4 + c4) + 4, INK, 'center', q.w, '12px sans-serif');
      txt(ctx, 't = Cα position, R = [e₁ e₂], θ = ' + deg(a4) + '°', W / 2, 50, SEC, 'center', q.w, '12px sans-serif');
    }

    // captions
    for (i = 0; i < 4; i++) {
      var w = ws[i].w;
      if (w < 0.01) continue;
      var fs = 13;
      ctx.font = '600 ' + fs + 'px sans-serif';
      while (ctx.measureText(TOP[i]).width > W - 16 && fs > 11) { fs--; ctx.font = '600 ' + fs + 'px sans-serif'; }
      txt(ctx, TOP[i], W / 2, 20, INK, 'center', w, '600 ' + fs + 'px sans-serif');
      var lines = wrap(ctx, BOT[i], W - 24);
      for (var j = 0; j < lines.length; j++) txt(ctx, lines[j], W / 2, H - 10 - (lines.length - 1 - j) * 16, SEC, 'center', w, '12px sans-serif');
    }
    // phase dots
    for (i = 0; i < 4; i++) {
      ctx.globalAlpha = 1; ctx.fillStyle = FAINT;
      ctx.beginPath(); ctx.arc(W / 2 + (i - 1.5) * 16, 33, 3, 0, 6.2832); ctx.fill();
      ctx.globalAlpha = ws[i].w; ctx.fillStyle = BLUE;
      ctx.beginPath(); ctx.arc(W / 2 + (i - 1.5) * 16, 33, 4.5, 0, 6.2832); ctx.fill();
    }
    ctx.globalAlpha = 1;
  }
};
